<?php
require_once __DIR__.'/config/config.php'; require_once __DIR__.'/includes/functions.php'; require_login();
if(!current_user_id()) redirect('/login.php');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['product_id']??0);$a=$_POST['action']??'';
 if($a==='add' && $pid>0){$s=$pdo->prepare('INSERT IGNORE INTO wishlists(user_id,product_id) VALUES(?,?)');$s->execute([current_user_id(),$pid]);flash('Product saved to your wishlist.');}
 if($a==='move_to_cart' && $pid>0){$q=$pdo->prepare('SELECT stock_quantity FROM products WHERE product_id=?');$q->execute([$pid]);$available=(int)$q->fetchColumn();if($available>0){$cart=get_or_create_cart($pdo,current_user_id());$q=$pdo->prepare('SELECT quantity FROM cart_items WHERE cart_id=? AND product_id=?');$q->execute([$cart,$pid]);$existing=(int)$q->fetchColumn();$qty=min($available,$existing+1);$up=$pdo->prepare('INSERT INTO cart_items(cart_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity)');$up->execute([$cart,$pid,$qty]);flash('Product moved to your cart.');}else flash('This product is currently out of stock.','error');}
 if($a==='remove' && $pid>0){$s=$pdo->prepare('DELETE FROM wishlists WHERE user_id=? AND product_id=?');$s->execute([current_user_id(),$pid]);flash('Product removed from your wishlist.');}
 redirect('/wishlist.php');
}
$s=$pdo->prepare('SELECT p.*,c.category_name FROM wishlists w JOIN products p ON p.product_id=w.product_id LEFT JOIN categories c ON c.category_id=p.category_id WHERE w.user_id=? ORDER BY w.created_at DESC');$s->execute([current_user_id()]);$products=$s->fetchAll();
$pageTitle='My Wishlist';require __DIR__.'/includes/header.php';
?>
<div class="page-head"><div><h1>My Wishlist</h1><p class="muted">Hardware products you saved for later.</p></div><a class="btn btn-outline" href="<?=BASE_URL?>/">Continue shopping</a></div>
<?php if(!$products):?><div class="card empty state-empty"><?=empty_art('Your wishlist is empty')?><h2>Your wishlist is empty</h2><p>Save products you are interested in and find them here.</p><a class="btn btn-primary" href="<?=BASE_URL?>/">Browse products</a></div><?php else:?><div class="grid product-grid"><?php foreach($products as $p):?><article class="card product-card"><a class="product-art" href="<?=BASE_URL?>/product.php?id=<?=$p['product_id']?>"><?=product_visual($p)?></a><div class="product-info"><h3><a href="<?=BASE_URL?>/product.php?id=<?=$p['product_id']?>"><?=e($p['product_name'])?></a></h3><div class="buy"><b class="price"><?=money($p['price'])?></b><?=stock_badge((int)$p['stock_quantity'])?></div><div class="grid u-gap-8"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="move_to_cart"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button class="btn btn-primary btn-block" <?= (int)$p['stock_quantity']<1?'disabled':'' ?>>Move to Cart</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button class="btn btn-outline btn-block">Remove from wishlist</button></form></div></div></article><?php endforeach;?></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php'; ?>